const now = new Date().toISOString();
const cred = $input.first().json;
return [{
  json: {
    ...cred,
    run_id: `gh-${now.replace(/[^0-9]/g, '').slice(0, 14)}-${Math.random().toString(36).slice(2, 8)}`,
    workflow_name: 'GH Compute — Pain Detector',
    started_at: now,
    finished_at: '',
    status: 'Started',
    sources_requested: 0,
    raw_items: 0,
    new_signals: 0,
    qualified_leads: 0,
    errors: '',
    details: 'Detector run started.'
  }
}];

const init = $('Initialize Run').first().json;
const cred = $('CREDENCIALS').first().json;
const rows = $input.all().map((item) => item.json);

const cfg = {};
for (const row of rows) {
  const key = String(row.key ?? row.Key ?? '').trim();
  if (key) cfg[key] = row.value ?? row.Value ?? '';
}

const errors = [];

const isEnabled = (value) => {
  if (value === true) return true;
  return String(value || '').trim().toLowerCase() === 'true';
};

const parseJson = (key) => {
  try {
    const raw = String(cfg[key] || '').trim();
    if (!raw) throw new Error(`${key} is empty`);
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) throw new Error(`${key} must be an array`);
    return parsed;
  } catch (error) {
    errors.push(`${key}: ${error.message}`);
    return [];
  }
};

const bool = (value) => {
  if (value === true) return true;
  return String(value || '').trim().toLowerCase() === 'true';
};

const numberValue = (configKey, credentialKey, fallback, min, max) => {
  const fromCred = cred[credentialKey];
  const raw = Number(fromCred ?? cfg[configKey]);
  const value = Number.isFinite(raw) ? raw : fallback;
  return Math.max(min, Math.min(max, Math.floor(value)));
};

const renderTemplate = (value, vars) => {
  if (Array.isArray(value)) return value.map((entry) => renderTemplate(entry, vars));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, renderTemplate(entry, vars)]));
  }
  if (typeof value === 'string') {
    return value
      .replaceAll('{{query}}', vars.query || '')
      .replaceAll('{{country}}', vars.country || '')
      .replaceAll('{{countryCode}}', vars.countryCode || '');
  }
  return value;
};

const queries = parseJson('SEARCH_QUERIES_JSON');
const sources = parseJson('APIFY_SOURCES_JSON');

if (!cred.google_sheet_id) errors.push('google_sheet_id is empty in CREDENCIALS');
if (!cred.openai_model) errors.push('openai_model is empty in CREDENCIALS');

const maxItems = numberValue('MAX_ITEMS_PER_QUERY', 'max_items_per_query', 20, 1, 100);
const maxRawChars = numberValue('MAX_RAW_TEXT_CHARACTERS', 'max_raw_text_characters', 6000, 500, 20000);
const pollInterval = numberValue('APIFY_POLL_INTERVAL_SECONDS', 'apify_poll_interval_seconds', 20, 5, 300);
const maxPolls = numberValue('APIFY_MAX_POLLS', 'apify_max_polls', 12, 1, 120);
const minQualifiedScore = numberValue('MIN_QUALIFIED_SCORE', 'min_qualified_score', 65, 0, 100);

const work = [];

for (const query of queries) {
  for (const source of sources) {
    const endpointUrl = String(source.endpoint_url || '').trim();
    if (!isEnabled(source.enabled)) continue;
    if (!endpointUrl) continue;

    work.push({
      json: {
        ...cred,
        work_item: true,
        run_id: init.run_id,
        workflow_name: init.workflow_name,
        started_at: init.started_at,
        query: String(query.query || ''),
        country: String(query.country || ''),
        countryCode: String(query.countryCode || ''),
        source_id: String(source.id || 'source'),
        source_mode: String(source.mode || 'actor_sync_dataset'),
        source_type: String(source.result_type || source.id || 'public_source'),
        endpoint_url: endpointUrl,
        apify_token_env_var: String(source.apify_token_env_var || cred.default_apify_token_env_var || 'APIFY_TOKEN_CLIENT_01').trim(),
        apify_input: renderTemplate(source.input_template || {}, query),
        max_items_per_query: maxItems,
        max_raw_text_characters: maxRawChars,
        poll_interval_seconds: pollInterval,
        max_polls: maxPolls,
        min_qualified_score: minQualifiedScore,
        summary_email_enabled: bool(cred.summary_email_enabled ?? cfg.SUMMARY_EMAIL_ENABLED),
        summary_email_to: String(cred.summary_email_to || cfg.SUMMARY_EMAIL_TO || 'hola@aimetos.com'),
        poll_attempt: 0,
        item_errors: errors.slice()
      }
    });
  }
}

if (!work.length) {
  return [{
    json: {
      ...cred,
      ...init,
      work_item: false,
      status: errors.length ? 'Failed' : 'Skipped',
      finished_at: new Date().toISOString(),
      sources_requested: sources.length,
      raw_items: 0,
      new_signals: 0,
      qualified_leads: 0,
      errors: errors.join('; '),
      details: errors.length
        ? 'No valid work items because mandatory configuration is missing or invalid.'
        : 'No enabled Apify source with configured endpoint_url.'
    }
  }];
}

return work;

const source = $('Loop Work Items').item.json;
const response = $input.first().json;
const statusCode = Number(response.statusCode || 0);
const payload = response.body ?? response;
const rawItems = Array.isArray(payload) ? payload : Array.isArray(payload.items) ? payload.items : [];
const errors = Array.isArray(source.item_errors) ? source.item_errors.slice() : [];
if (statusCode === 401 || statusCode === 403) errors.push(`Apify authentication failed for ${source.source_id}`);
if (statusCode === 402) errors.push(`Apify payment required for ${source.source_id}; review ${source.apify_token_env_var}`);
if (statusCode >= 400 && statusCode !== 429 && statusCode < 500) errors.push(`Apify request rejected ${statusCode} for ${source.source_id}`);
return [{ json: { ...source, apify_status: statusCode ? `HTTP_${statusCode}` : 'OK', raw_items_payload: rawItems, raw_items_count: rawItems.length, item_errors: errors } }];

const source = $('Wait Before Poll').item.json;
const response = $input.first().json;
const body = response.body || response;
const run = body.data || body;
const statusCode = Number(response.statusCode || 0);
const status = String(run.status || source.apify_status || (statusCode ? `HTTP_${statusCode}` : 'UNKNOWN'));
const errors = Array.isArray(source.item_errors) ? source.item_errors.slice() : [];
const pollAttempt = Number(source.poll_attempt || 0) + 1;
const temporaryHttp = statusCode === 429 || statusCode >= 500;
const running = ['READY', 'RUNNING', 'TIMING-OUT'].includes(status) || temporaryHttp;
const terminalBad = ['FAILED', 'ABORTED', 'TIMED-OUT'].includes(status);
if (terminalBad) errors.push(`Apify run ${source.apify_run_id} ended as ${status}: ${run.statusMessage || ''}`.trim());
if (statusCode >= 400 && !temporaryHttp) errors.push(`Apify poll returned HTTP ${statusCode}`);
return [{ json: { ...source, apify_status: status, apify_status_message: run.statusMessage || source.apify_status_message || '', default_dataset_id: run.defaultDatasetId || source.default_dataset_id || '', poll_attempt: pollAttempt, should_poll: running && pollAttempt < Number(source.max_polls || 12), run_succeeded: status === 'SUCCEEDED' && !!(run.defaultDatasetId || source.default_dataset_id), item_errors: errors } }];

const crypto = require('crypto');
const context = $('Attach Start Result').item.json;
const rawItems = Array.isArray(context.raw_items_payload) ? context.raw_items_payload : [];
const cleanText = (value) => String(value ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const normalizeUrl = (value) => {
  try {
    const url = new URL(String(value || '').trim());
    url.hash = '';
    url.search = '';
    return url.toString().replace(/\/$/, '');
  } catch (error) {
    return '';
  }
};
const socialUrl = (value) => /(linkedin\.com|facebook\.com|instagram\.com|x\.com|twitter\.com)/i.test(value || '');
const out = [];
const seen = new Set();
for (const item of rawItems.slice(0, Number(context.max_items_per_query || 20))) {
  if (!item || typeof item !== 'object') continue;
  const sourceUrl = normalizeUrl(item.url || item.link || item.source_url || item.sourceUrl || item.website);
  if (!sourceUrl) continue;
  const title = cleanText(item.title || item.jobTitle || item.position || item.name);
  const company = cleanText(item.company || item.companyName || item.company_name || item.employer || item.organization);
  const text = cleanText([title, item.description, item.snippet, item.text, item.raw_text, item.summary, item.location].filter(Boolean).join(' ')).slice(0, Number(context.max_raw_text_characters || 6000));
  if (!company || text.length < 40) continue;
  if (!/(grasshopper|rhino|parametric|computational|facade|fabrication|optimization|optimisation|simulation|karamba|ladybug|honeybee|kangaroo|galapagos|wallacei|opossum|hops|shapediver|rhino\.inside|digital design|generative design|automation|automatizaci[oó]n|diseño param[eé]trico|fabricaci[oó]n digital)/i.test(`${title} ${text}`)) continue;
  const website = !socialUrl(item.website) ? normalizeUrl(item.website) : '';
  let domain = '';
  try { domain = new URL(website || sourceUrl).hostname.replace(/^www\./, ''); } catch (error) {}
  const dedupeBase = sourceUrl || `${company}|${title}|${text.slice(0, 140)}`;
  const dedupeKey = crypto.createHash('sha256').update(dedupeBase.toLowerCase()).digest('hex');
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);
  out.push({ json: { run_id: context.run_id, source_id: context.source_id, source_type: context.source_type, company_name: company, website, domain, country: context.country, source_url: sourceUrl, source_title: title, raw_text: text, raw_item_json: JSON.stringify(item), detected_at: new Date().toISOString(), dedupe_key: dedupeKey, min_qualified_score: context.min_qualified_score, item_errors: context.item_errors || [] } });
}
return out;

const current = $('Normalize Results').item.json;
const existing = new Set($input.all().map((item) => String(item.json.dedupe_key || '').trim()).filter(Boolean));
if (existing.has(current.dedupe_key)) return [];
return [{ json: current }];

const source = $('Filter New Signals').item.json;
const response = $input.first().json;
const body = response.body || response;
let text = '';
if (Array.isArray(body.output)) {
  for (const block of body.output) for (const content of (block.content || [])) if (content.type === 'output_text') text += content.text || '';
}
text = text || body.output_text || body.text || '';
let classification = null;
let error = '';
try {
  classification = typeof text === 'object' ? text : JSON.parse(String(text));
} catch (parseError) {
  error = `Invalid OpenAI JSON: ${parseError.message}`;
}
const allowedCategory = ['performance','iterations','automation','hiring_signal','no_clear_pain'];
const allowedStrength = ['high','medium','low'];
if (classification && (typeof classification.is_relevant !== 'boolean' || !allowedCategory.includes(classification.pain_category) || !allowedStrength.includes(classification.evidence_strength))) {
  error = 'Malformed classification schema';
  classification = null;
}
if (!classification) {
  classification = { is_relevant: false, pain_category: 'no_clear_pain', pain_summary: '', pain_hypothesis: '', pain_signal: '', evidence_quote: '', evidence_strength: 'low', buyer_role: '', recommended_service: 'No recomendado', outreach_angle: '', reason: '', excluded_reason: error || 'No valid classification.' };
}
return [{ json: { ...source, classification, classification_valid: !error, item_errors: error ? [...(source.item_errors || []), error] : (source.item_errors || []) } }];

const item = $input.first().json;
const c = item.classification || {};
if (c.is_relevant !== true) {
  return [{ json: { ...item, score: 0, priority: 'C', next_action: 'Conservar como señal; no contactar' } }];
}
const haystack = `${item.source_title || ''} ${item.raw_text || ''} ${c.pain_signal || ''} ${c.pain_summary || ''}`.toLowerCase();
let score = 20;
if (c.evidence_strength === 'high') score += 30;
if (c.evidence_strength === 'medium') score += 15;
score += ({ performance: 25, iterations: 20, automation: 20, hiring_signal: 10, no_clear_pain: 0 }[c.pain_category] || 0);
if (/(rhino|grasshopper|computational design|parametric design|diseño computacional|diseño paramétrico)/i.test(haystack)) score += 10;
if (/(optimization|optimisation|simulation|facade|fachada|digital fabrication|additive manufacturing|generative design|fabricación digital)/i.test(haystack)) score += 10;
if (/(slow|crash|freeze|freezes|hours|heavy|large model|batch|multiple variants|automation|lento|bloquea|crashea|horas|pesad[ao]|variantes|automatización)/i.test(haystack)) score += 20;
score = Math.min(score, 100);
const priority = score >= 80 ? 'A' : score >= 65 ? 'B' : 'C';
const next_action = priority === 'A' ? 'Revisar empresa y localizar decisor en Sales Navigator en 24 horas' : priority === 'B' ? 'Validar decisor y evidencia antes de contactar' : 'Conservar como señal; no contactar';
return [{ json: { ...item, score, priority, next_action } }];

const crypto = require('crypto');
return $input.all().map((item) => {
  const j = item.json;
  const c = j.classification || {};
  const now = new Date().toISOString();
  const companyId = 'co_' + crypto.createHash('sha256').update(String(j.domain || j.company_name).toLowerCase()).digest('hex').slice(0, 16);
  return { json: { signal_id: 'sig_' + crypto.createHash('sha256').update(j.dedupe_key).digest('hex').slice(0, 16), company_id: companyId, company_name: j.company_name, source_url: j.source_url, source_type: j.source_type, source_title: j.source_title, raw_text: j.raw_text, pain_category: c.pain_category || 'no_clear_pain', pain_signal: c.pain_signal || '', evidence_quote: c.evidence_quote || '', evidence_strength: c.evidence_strength || 'low', detected_at: j.detected_at, analyzed_at: now, status: c.is_relevant ? (j.score >= Number(j.min_qualified_score || 65) ? 'Cualificado' : 'Clasificado') : 'Descartado', dedupe_key: j.dedupe_key, run_id: j.run_id, score: j.score, priority: j.priority, next_action: j.next_action, website: j.website, domain: j.domain, country: j.country, classification: c, min_qualified_score: j.min_qualified_score } };
});

const now = new Date().toISOString();
return $input.all().map((item) => {
  const j = item.json;
  return { json: { company_id: j.company_id, company_name: j.company_name, website: j.website, domain: j.domain, linkedin_company_url: '', country: j.country, city: '', sector: '', company_size: '', source: j.source_type, first_seen_at: j.detected_at || now, last_seen_at: now, status: j.score >= Number(j.min_qualified_score || 65) ? 'Analizando' : 'Nuevo', notes: `Última señal: ${j.source_url}` } };
});

const crypto = require('crypto');
const now = new Date().toISOString();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const c = j.classification || {};
  if (j.score < Number(j.min_qualified_score || 65) || c.is_relevant !== true) continue;
  out.push({ json: { lead_id: 'lead_' + crypto.createHash('sha256').update(`${j.company_id}|${j.source_url}`).digest('hex').slice(0, 16), company_id: j.company_id, company_name: j.company_name, website: j.website, domain: j.domain, country: j.country, sector: '', decision_maker_name: '', decision_maker_role: '', linkedin_url: '', email: '', email_source: '', enrichment_status: 'Pending', pain_summary: c.pain_summary || '', pain_hypothesis: c.pain_hypothesis || '', recommended_service: c.recommended_service || '', outreach_angle: c.outreach_angle || '', score: j.score, priority: j.priority, evidence_strength: c.evidence_strength || 'low', source_url: j.source_url, lead_status: 'Pending review', outreach_status: 'Pending', next_action: j.next_action, created_at: now, updated_at: now, last_seen_at: now, notes: c.reason || '' } });
}
return out;

const j = $input.first().json;
const run = $('Initialize Run').first().json;
const errors = Array.isArray(j.item_errors) ? j.item_errors.join('; ') : '';
return [{ json: { run_id: run.run_id, workflow_name: run.workflow_name, started_at: run.started_at, finished_at: new Date().toISOString(), status: errors ? 'Completed with errors' : 'Completed', sources_requested: 1, raw_items: 0, new_signals: 0, qualified_leads: 0, errors, details: `Source ${j.source_id || ''} did not produce a successful dataset. Status: ${j.apify_status || 'unknown'}` } }];
